INSERT INTO message (id, thread_id, sender_id, sent_at, body, priority) VALUES
    ('1ad95bbc-cfed-5dc0-bf58-4ac6587e14d0', '93e35d57-19fe-573b-8dbf-44f29d69af5c', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', now() - interval '4 hours', 'Panie doktorze, pacjent Kowalski zgłasza duszność przy zmianie pozycji. Bilans płynów za dobę dodatni.', 'high'),
    ('881b100e-f469-5335-99c0-3dd96c58e7ae', '93e35d57-19fe-573b-8dbf-44f29d69af5c', '16259545-f97c-531d-b9cd-6ba115379372', now() - interval '3 hours', 'Proszę zwiększyć dawkę furosemidu do 40 mg dwa razy dziennie i skontrolować elektrolity jutro rano.', 'normal'),
    ('f6aeb5c1-4a3b-5db2-b42e-b2c860674261', '93e35d57-19fe-573b-8dbf-44f29d69af5c', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', now() - interval '1 hours', 'Dawka podana zgodnie z zaleceniem. Pacjent czuje się lepiej.', 'normal'),
    ('a26956e5-e6c0-5b2f-ba44-cb791d30ccbd', 'd287dcc0-bbbf-5998-9a7b-f773cf7f57d1', '6a2063f1-ade9-52c8-a1b0-f894c0093d46', now() - interval '5 hours', 'Proszę o kontrolę parametrów życiowych co 2h po zabiegu koronarografii.', 'high'),
    ('61427bd7-734a-500f-a0c8-ef9ba5365936', 'd287dcc0-bbbf-5998-9a7b-f773cf7f57d1', 'f9dd7885-41c2-5cf0-a4ca-2a5b45474502', now() - interval '3 hours', 'Parametry stabilne, miejsce wkłucia bez cech krwiaka.', 'normal'),
    ('bffec0a5-ce78-5c39-9422-6d107029525b', '28ddda82-8247-5f25-972a-27f6ff75e92c', '16259545-f97c-531d-b9cd-6ba115379372', now() - interval '22 hours', 'Proszę o pilną konsultację kardiologiczną dla pacjenta z sali 204 - narastające obrzęki.', 'high'),
    ('c5defc4e-7c2e-5a08-b8cf-620bad73e3da', '28ddda82-8247-5f25-972a-27f6ff75e92c', '6a2063f1-ade9-52c8-a1b0-f894c0093d46', now() - interval '20 hours', 'Przyjdę po popołudniowym obchodzie, ok. godz. 15:00.', 'normal'),
    ('7d9145ad-a2df-53a8-aa83-e98113d34450', 'aceb453e-e3ac-571e-a371-d221f64bd6a8', '0ffcc103-5e1d-5346-aeba-8f9907cce3df', now() - interval '8 hours', 'Jak przebiega dzisiejsza rehabilitacja pacjentki Kamińskiej?', 'normal'),
    ('54a964e9-8bdc-50a8-8fd2-5db057c3f08e', 'aceb453e-e3ac-571e-a371-d221f64bd6a8', '42fb062f-6dc8-574b-b1bd-fc33c5e4decb', now() - interval '7 hours', 'Siła mięśniowa kończyny górnej poprawiła się do 4/5. Pacjentka współpracuje bardzo dobrze.', 'normal'),
    ('9c664d08-4d8a-506f-bf12-82fa0460b81c', 'aceb453e-e3ac-571e-a371-d221f64bd6a8', '42fb062f-6dc8-574b-b1bd-fc33c5e4decb', now() - interval '6 hours', 'Proszę o decyzję odnośnie zwiększenia intensywności ćwiczeń od jutra.', 'normal'),
    ('d6c738ab-b7db-52e4-a9ec-5e3b78a4a1c2', 'fe922873-864c-5398-8d89-1d5bd2f36622', '19d27aee-1c46-5dd5-a0a4-21da1fe3cf3e', now() - interval '11 hours', 'Proszę przygotować salę operacyjną nr 2 na jutro godz. 8:00, cholecystektomia laparoskopowa.', 'normal'),
    ('a9dc28ed-a2a7-50a5-aab6-bc99521d0b62', 'fe922873-864c-5398-8d89-1d5bd2f36622', '570c2cc4-eafe-5082-a1ca-e47097316d3a', now() - interval '10 hours', 'Sala przygotowana, pacjent poinformowany o zabiegu.', 'normal'),
    ('ab40b6b2-5d4d-5bda-942a-cec67f04e750', '427acd53-6745-5d54-a697-caf7a351d482', 'fdf3ef3c-c118-5896-aa53-c2eff5aa7a21', now() - interval '3 hours', 'Kto obejmuje dyżur nocny na SOR w ten weekend?', 'normal'),
    ('c6a6149d-3cdc-5347-943d-ce88eca3d6ff', '427acd53-6745-5d54-a697-caf7a351d482', 'fbda300f-3c9a-515b-9a3b-ad2b1a7d9775', now() - interval '2 hours', 'Ja biorę sobotę, w niedzielę jest pielęgniarka Kaczmarek.', 'normal');
