INSERT INTO handoff_note (id, ward_id, shift_date, shift, from_id, to_id, created_at, general_notes) VALUES
    ('a186b9a2-556b-58c5-8ca1-087857b97dfa', '25c25490-5067-5aaa-bcf5-5dc23f56588b', CURRENT_DATE, 'day', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', 'f9dd7885-41c2-5cf0-a4ca-2a5b45474502', now() - interval '1 hours', 'Oddział pełny, brak wolnych łóżek. Zwrócić uwagę na pacjentów z ryzykiem upadku.'),
    ('286fa5dc-4237-5c44-abf3-f7e19c180acc', '36877e50-4f0b-5b6c-bc22-983228fe0d83', CURRENT_DATE, 'night', 'f9dd7885-41c2-5cf0-a4ca-2a5b45474502', '625e824c-3b63-51c2-9e56-78cbfd0ff9a5', now() - interval '12 hours', 'Jeden pacjent po zabiegu koronarografii, wymaga monitorowania miejsca wkłucia.'),
    ('ee715576-70bc-552a-a319-be5aede82453', '1839f924-5e1b-5ceb-963f-f2ee1592947a', CURRENT_DATE - 1, 'night', 'fbda300f-3c9a-515b-9a3b-ad2b1a7d9775', '42fb062f-6dc8-574b-b1bd-fc33c5e4decb', now() - interval '28 hours', 'Spokojny dyżur, jeden pacjent urazowy przekazany na oddział chirurgii.');
INSERT INTO handoff_patient_note (handoff_id, patient_id, situation, background, assessment, recommendation) VALUES
    ('a186b9a2-556b-58c5-8ca1-087857b97dfa', 'c078186c-c437-5fa8-8a5b-a6bf8883f8bf', 'Pacjent z zaostrzeniem niewydolności serca, 3. doba hospitalizacji.', 'Wywiad nadciśnienia i cukrzycy typu 2, leczony ambulatoryjnie.', 'Bilans płynów dodatni, obrzęki zmniejszają się po zwiększeniu dawki furosemidu.', 'Kontynuować leczenie diuretyczne, kontrola elektrolitów rano.'),
    ('a186b9a2-556b-58c5-8ca1-087857b97dfa', '55cc6e9e-6413-58bc-88b6-6342579d8413', 'Pacjentka z przewlekłą chorobą nerek, zaburzenia elektrolitowe.', 'Przeniesiona z innego ośrodka 7 dni temu, wysokie ryzyko upadku.', 'Stan stabilny po korekcie potasu, nadal wymaga częstej kontroli.', 'Kontrola elektrolitów co 12h, zabezpieczenia przeciwupadkowe.'),
    ('286fa5dc-4237-5c44-abf3-f7e19c180acc', '7466c824-06b6-57f2-8bae-2f20f77d64b6', 'Pacjentka po angioplastyce ze stentem, 1. doba po zabiegu.', 'Przyjęta z ostrym zespołem wieńcowym, bez powikłań okołozabiegowych.', 'Parametry stabilne, miejsce wkłucia bez cech krwiaka.', 'Kontrola parametrów co 4h, pionizacja zgodnie z zaleceniem lekarskim.'),
    ('ee715576-70bc-552a-a319-be5aede82453', '50c8f3fa-ea66-581a-9207-f9c4c7131d26', 'Pacjent po wypadku komunikacyjnym, triage czerwony.', 'Uraz wielonarządowy, wykonano TK całego ciała.', 'Stan stabilny po wstępnym zaopatrzeniu, obserwacja neurologiczna.', 'Kontynuować obserwację, kontrola TK głowy za 24h.');
